x;object-fit:cover;display:none}.qr-camera #html5-reader{display:none;height:310px}.qr-camera #html5-reader video{display:block!important;height:310px!important;object-fit:cover}.qr-guide{position:absolute;inset:20% 30%;border:3px solid #00c3bd;border-radius:12px;pointer-events:none}.qr-camera-help{padding:90px 30px;color:#fff;text-align:center}.qr-camera-help i{font-size:42px;color:#3dd5cb;display:block;margin-bottom:15px}@media(max-width:991px){.qr-status-panel{margin-top:20px}.qr-hero{padding:20px}.qr-shell{padding:16px}}
