<?php if ($settings['camera_enabled']) { ?><script src="<?php echo base_url('backend/qrattendance/html5-qrcode.min.js'); ?>"></script><?php } ?>
<script>
(function(){
    var input=document.getElementById('scan-code'), status=document.getElementById('scan-result'), cameraStatus=document.getElementById('camera-result'), busy=false, stream=null, html5Scanner=null;
    function escapeHtml(value){var e=document.createElement('div');e.textContent=value||'';return e.innerHTML;}
    function renderCameraReady(){if(!cameraStatus)return;cameraStatus.innerHTML='<div class="qr-empty"><div class="qr-symbol" style="color:#00a99d"><i class="fa fa-camera"></i></div><h4>Camera ready</h4><p><span class="label label-success"><i class="fa fa-circle"></i> SCANNING ACTIVE</span></p><p>Hold the staff QR code inside the scan frame.</p></div>';}
    function render(data,target){target=target||status;var staff=data.staff||{}, good=Number(data.status)===1, warning=Number(data.status)===2, type=good?'success':(warning?'warning':'danger');if(!staff.name){target.innerHTML='<div class="qr-empty"><div class="qr-symbol"><i class="fa fa-exclamation-circle"></i></div><h4>'+escapeHtml(data.message||'Scan could not be completed')+'</h4><p>Please check the staff card and try again.</p></div>';return;}target.innerHTML='<div class="qr-result-card"><div class="qr-person-icon"><i class="fa fa-user"></i></div><div class="qr-person-name">'+escapeHtml(staff.name+' '+(staff.surname||''))+'</div><div class="qr-person-meta">'+escapeHtml(staff.employee_id||'')+(staff.role_name?' &middot; '+escapeHtml(staff.role_name):'')+'</div><div class="alert alert-'+type+' qr-result-alert"><strong><i class="fa fa-'+(good?'check-circle':'exclamation-circle')+'"></i> '+escapeHtml(data.message||'')+'</strong>'+(data.attendance?'<br><small>In: '+escapeHtml(data.attendance.in_time||'—')+' &nbsp; | &nbsp; Out: '+escapeHtml(data.attendance.out_time||'—')+'</small>':'')+'</div></div>';}
    function submit(code,target){if(!code||busy)return;busy=true;var csrf=document.getElementById('qr-csrf'),payload={code:code};payload[csrf.name]=csrf.value;$.ajax({url:'<?php echo site_url('admin/qrattendance/attendance/scan'); ?>',type:'POST',data:payload,dataType:'json'}).done(function(data){if(data.csrf_hash){csrf.value=data.csrf_hash;}render(data,target);}).fail(function(xhr){var response=xhr.responseJSON;if(!response&&xhr.responseText){try{response=JSON.parse(xhr.responseText);}catch(e){}}render(response||{status:0,message:'Attendance request failed (HTTP '+xhr.status+'). Check the server error log.'},target);}).always(function(){busy=false;if(input){input.value='';input.focus();}});}
    if(input){input.addEventListener('keydown',function(event){if(event.key==='Enter'){event.preventDefault();submit(input.value.trim());}});}
    var button=document.getElementById('start-camera');if(button){button.addEventListener('click',function(){if(!window.isSecureContext){return render({status:0,message:'Camera access requires HTTPS. Open this hospital URL using https:// and try again.'},cameraStatus);}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){return render({status:0,message:'Camera access is not supported by this browser. Use current Chrome or Edge.'},cameraStatus);}if(!('BarcodeDetector' in window)&&window.Html5Qrcode){return startHtml5Decoder();}navigator.mediaDevices.getUserMedia({video:{facingMode:'<?php echo $settings['camera_facing_mode']; ?>'}}).then(function(s){stream=s;var video=document.getElementById('camera-video');video.srcObject=s;video.style.display='block';video.play();document.getElementById('camera-help').style.display='none';button.disabled=true;button.innerHTML='<i class="fa fa-check"></i> Camera started';renderCameraReady();if('BarcodeDetector' in window){detect(video);}else{startHtml5Decoder();}}).catch(cameraError);});}
    function startHtml5Decoder(){var reader=document.getElementById('html5-reader');if(!reader||!window.Html5Qrcode){return render({status:0,message:'QR decoder could not be loaded. Please refresh the page and try again.'},cameraStatus);}document.getElementById('camera-help').style.display='none';document.querySelector('.qr-guide').style.display='none';reader.style.display='block';html5Scanner=new Html5Qrcode('html5-reader');html5Scanner.start({facingMode:'<?php echo $settings['camera_facing_mode']; ?>'},{fps:10,qrbox:{width:250,height:250},aspectRatio:1.5},function(decodedText){submit(decodedText,cameraStatus);},function(){}).then(function(){button.disabled=true;button.innerHTML='<i class="fa fa-check"></i> Camera started';renderCameraReady();}).catch(cameraError);}
    function cameraError(error){var message=error&&error.name==='NotAllowedError'?'Camera permission was blocked. Click the camera icon in the browser address bar and allow access.':(error&&error.name==='NotFoundError'?'No camera device was found. Connect a webcam and try again.':'Unable to start the camera. Please close other apps using it and try again.');render({status:0,message:message},cameraStatus);}
    function detect(video){var detector;try{detector=new BarcodeDetector({formats:['qr_code','code_128','ean_13']});}catch(e){render({status:2,message:'Camera is ready. Use the barcode input if QR detection is unavailable.'},cameraStatus);return;}(function loop(){if(!stream)return;detector.detect(video).then(function(codes){if(codes.length)submit(codes[0].rawValue,cameraStatus);}).catch(function(){}).then(function(){setTimeout(loop,500);});})();}
    window.addEventListener('beforeunload',function(){if(stream)stream.getTracks().forEach(function(track){track.stop();});if(html5Scanner)html5Scanner.stop().catch(function(){});});
})();
</script>
